167|    private function buildPreview($row, int $rowNumber): void
168|    {
169|        // Map CSV columns to person fields
170|        $data = $this->mapRowToData($row);
171|
172|        // Validate required fields
173|        if (empty($data['n_code']) || empty($data['f_name']) || empty($data['l_name'])) {
174|            $this->importResults['preview'][] = [
