202|                    'row' => $rowNumber,
203|                    'status' => 'error',
204|                    'message' => "واحد {$unit->name} در واحدهای قابل دسترس شما نیست",
205|                    'data' => $data,
206|                ];
207|                $this->importResults['skipped']++;
208|
209|                return;
210|            }
211|        } else {
212|            $this->importResults['preview'][] = [
213|                'row' => $rowNumber,
214|                'status' => 'error',
215|                'message' => 'شناسه واحد (u_id) خالی است',
216|                'data' => $data,
217|            ];
218|            $this->importResults['skipped']++;
219|
220|            return;
