222|
223|        // Verify related models exist (using pre-loaded data)
224|        $validationError = $this->validateRelatedModels($data);
225|        if ($validationError) {
226|            $this->importResults['preview'][] = [
227|                'row' => $rowNumber,
228|                'status' => 'error',
229|                'message' => $validationError,
230|                'data' => $data,
231|            ];
232|            $this->importResults['skipped']++;
233|
234|            return;
235|        }
236|
237|        // Find existing record by n_code
238|        $existing = $this->findExistingRecord($data);
239|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
240|
241|        if ($existing) {
242|            $changes = $this->detectChanges($existing['record'], $data);
243|
244|            if (! empty($changes)) {
245|                $this->importResults['preview'][] = [
246|                    'row' => $rowNumber,
