279|    private function findExistingRecord(array $data): ?array
280|    {
281|        $existing = null;
282|        $matchKey = null;
283|
284|        if (! empty($data['n_code']) && isset($this->existingRecords['n_code'][$data['n_code']])) {
285|            $existing = $this->existingRecords['n_code'][$data['n_code']];
286|            $matchKey = 'n_code';
287|        }
288|
289|        if ($existing) {
