302|            'l_name' => $this->clean($row['l_name'] ?? null),
303|            't_id' => $this->parseInt($row['t_id'] ?? null),
304|            'e_id' => $this->parseInt($row['e_id'] ?? null),
305|            'r_id' => $this->parseInt($row['r_id'] ?? null),
306|            's_id' => $this->parseInt($row['s_id'] ?? null),
307|            'u_id' => $this->parseInt($row['u_id'] ?? null),
308|            'phone' => $this->clean($row['phone'] ?? null),
309|        ];
310|    }
