312|    private function validateRelatedModels(array $data): ?string
313|    {
314|        if (! empty($data['t_id']) && ! isset($this->tahsils[$data['t_id']])) {
315|            return "تحصیلات با شناسه {$data['t_id']} یافت نشد";
316|        }
317|        if (! empty($data['e_id']) && ! isset($this->estekhdams[$data['e_id']])) {
318|            return "نوع استخدام با شناسه {$data['e_id']} یافت نشد";
319|        }
320|        if (! empty($data['r_id']) && ! isset($this->radifs[$data['r_id']])) {
321|            return "ردیف سازمانی با شناسه {$data['r_id']} یافت نشد";
322|        }
323|        if (! empty($data['s_id']) && ! isset($this->semats[$data['s_id']])) {
324|            return "سمت با شناسه {$data['s_id']} یافت نشد";
325|        }
326|
327|        return null;
328|    }
