330|    private function processRow(array $row, int $rowNumber, string $action = 'auto', bool $isConfirmation = false): void
331|    {
332|        $data = $this->mapRowToData($row);
333|
334|        // Validate required fields
335|        if (empty($data['n_code']) || empty($data['f_name']) || empty($data['l_name'])) {
336|            $this->importResults['errors'][] = [
337|                'row' => $rowNumber,
338|                'error' => 'Missing required fields: n_code, f_name, l_name are required',
339|                'data' => $data,
340|            ];
341|            $this->importResults['skipped']++;
342|
343|            return;
344|        }
345|
346|        // Verify unit exists and is in accessible units (using pre-loaded data)
347|        $unit = $this->units[$data['u_id']] ?? null;
348|        if (! $unit) {
349|            $this->importResults['errors'][] = [
350|                'row' => $rowNumber,
351|                'error' => "Unit with id {$data['u_id']} not found",
352|                'data' => $data,
353|            ];
354|            $this->importResults['skipped']++;
355|
356|            return;
357|        }
358|
359|        if (! empty($this->accessibleUnitIds) && ! in_array($unit->id, $this->accessibleUnitIds)) {
360|            $this->importResults['errors'][] = [
361|                'row' => $rowNumber,
362|                'error' => "Unit {$data['u_id']} is not in your accessible units",
363|                'data' => $data,
364|            ];
365|            $this->importResults['skipped']++;
366|
367|            return;
368|        }
369|
370|        // Verify related models exist (using pre-loaded data)
371|        $validationError = $this->validateRelatedModels($data);
372|        if ($validationError) {
373|            $this->importResults['errors'][] = [
374|                'row' => $rowNumber,
375|                'error' => $validationError,
376|                'data' => $data,
377|            ];
378|            $this->importResults['skipped']++;
379|
380|            return;
381|        }
382|
383|        // Find existing record by n_code
384|        $existing = $this->findExistingRecord($data);
385|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
386|
387|        if ($existing) {
388|            // Check for changes
389|            $changes = $this->detectChanges($existing['record'], $data);
390|
391|            if (! empty($changes)) {
392|                $this->importResults['changes'][] = [
393|                    'row' => $rowNumber,
394|                    'n_code' => $existing['record']->n_code,
395|                    'match_key' => $matchKey,
396|                    'changes' => $changes,
397|                ];
398|
399|                // Update the record
400|                if ($action === 'update' || $action === 'auto') {
401|                    $existing['record']->update($data);
402|                    $this->importResults['updated']++;
403|                }
404|            } else {
405|                $this->importResults['skipped']++;
406|            }
407|        } else {
408|            // Create new record
409|            if ($action === 'create' || $action === 'auto') {
410|                Person::create($data);
411|                $this->importResults['created']++;
412|            }
413|        }
