416|    private function detectChanges(Person $existing, array $newData): array
417|    {
418|        $changes = [];
419|        $compareFields = ['f_name', 'l_name', 't_id', 'e_id', 'r_id', 's_id', 'u_id', 'phone'];
420|
421|        foreach ($compareFields as $field) {
422|            $oldValue = $existing->$field;
423|            $newValue = $newData[$field] ?? null;
424|
425|            // Normalize for comparison
426|            $oldNormalized = $this->normalizeForComparison($oldValue);
427|            $newNormalized = $this->normalizeForComparison($newValue);
428|
429|            if ($oldNormalized !== $newNormalized) {
430|                $changes[$field] = [
431|                    'old' => $oldValue,
432|                    'new' => $newValue,
433|                ];
434|            }
435|        }
436|
437|        return $changes;
438|    }
