173|                'status' => 'error',
174|                'message' => "پرسنل {$data['n_code']} در واحدهای قابل دسترس شما نیست",
175|                'data' => $data,
176|            ];
177|            $this->importResults['skipped']++;
178|
179|            return;
180|        }
181|
182|        // Find existing record
183|        $existing = $this->findExistingRecord($data);
184|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
185|
186|        if ($existing) {
