191|                    'row' => $rowNumber,
192|                    'status' => 'update',
193|                    'id' => $existing['record']->id,
194|                    'pc_name' => $existing['record']->pc_name,
195|                    'match_key' => $matchKey,
196|                    'changes' => $changes,
197|                    'person' => $person->f_name.' '.$person->l_name,
198|                    'data' => $data,
199|                ];
200|                $this->importResults['updated']++;
201|            } else {
202|                $this->importResults['preview'][] = [
