217|                'status' => 'create',
218|                'pc_name' => $data['pc_name'],
219|                'person' => $person->f_name.' '.$person->l_name,
220|                'data' => $data,
221|            ];
222|            $this->importResults['created']++;
223|        }
224|    }
225|
226|    private function findExistingRecord(array $data): ?array
227|    {
228|        $existing = null;
229|        $matchKey = null;
230|
231|        if (in_array($this->compareKey, ['pc_name', 'both']) && ! empty($data['pc_name']) && isset($this->existingRecords['pc_name'][$data['pc_name']])) {
232|            $existing = $this->existingRecords['pc_name'][$data['pc_name']];
233|            $matchKey = 'pc_name';
234|        } elseif (in_array($this->compareKey, ['mac', 'both']) && ! empty($data['mac']) && isset($this->existingRecords['mac'][$data['mac']])) {
235|            $existing = $this->existingRecords['mac'][$data['mac']];
236|            $matchKey = 'mac';
237|        }
238|
239|        if ($existing) {
240|            return ['record' => $existing, 'key' => $matchKey];
241|        }
242|
243|        return null;
244|    }
245|
246|    private function mapRowToData(array $row): array
247|    {
248|        return [
249|            'n_code' => $this->clean($row['n_code'] ?? null),
250|            'pc_name' => $this->clean($row['pc_name'] ?? null),
251|            'type' => $this->clean($row['type'] ?? null),
252|            'os' => $this->clean($row['os'] ?? null),
253|            'ip_valid' => $this->clean($row['ip_valid'] ?? null),
254|            'ip_local' => $this->clean($row['ip_local'] ?? null),
255|            'mac' => $this->clean($row['mac'] ?? null),
256|            'net_type' => $this->clean($row['net_type'] ?? null),
257|            'switch' => $this->clean($row['switch'] ?? null),
258|            'port' => $this->clean($row['port'] ?? null),
259|            'shutdown' => $this->parseBoolean($row['shutdown'] ?? null) ?? false,
260|            'vlan' => $this->clean($row['vlan'] ?? null),
261|            'motherboard' => $this->clean($row['motherboard'] ?? null),
262|            'cpu' => $this->clean($row['cpu'] ?? null),
263|            'ram' => $this->clean($row['ram'] ?? null),
264|            'hdd' => $this->clean($row['hdd'] ?? null),
265|            'comments' => $this->clean($row['comments'] ?? null),
266|            'mark' => $this->parseBoolean($row['mark'] ?? null) ?? false,
267|            'clean_at' => $this->parseDate($row['clean_at'] ?? null),
268|        ];
269|    }
270|
271|    private function processRow(array $row, int $rowNumber, string $action = 'auto', bool $isConfirmation = false): void
272|    {
273|        $data = $this->mapRowToData($row);
274|
275|        // Validate required fields
276|        if (empty($data['n_code']) || empty($data['pc_name'])) {
277|            $this->importResults['errors'][] = [
278|                'row' => $rowNumber,
279|                'error' => 'Missing required fields: n_code and pc_name are required',
280|                'data' => $data,
281|            ];
282|            $this->importResults['skipped']++;
283|
284|            return;
285|        }
286|
287|        // Verify person exists and is in accessible units
288|        $person = $this->existingPersons[$data['n_code']] ?? null;
289|        if (! $person) {
290|            $this->importResults['errors'][] = [
291|                'row' => $rowNumber,
292|                'error' => "Person with n_code {$data['n_code']} not found",
293|                'data' => $data,
294|            ];
295|            $this->importResults['skipped']++;
296|
297|            return;
298|        }
299|
300|        if (! empty($this->accessibleUnitIds) && ! in_array($person->u_id, $this->accessibleUnitIds)) {
301|            $this->importResults['errors'][] = [
302|                'row' => $rowNumber,
303|                'error' => "Person {$data['n_code']} is not in your accessible units",
304|                'data' => $data,
305|            ];
306|            $this->importResults['skipped']++;
307|
308|            return;
309|        }
310|
311|        // Find existing record by pc_name or mac
312|        $existing = $this->findExistingRecord($data);
313|        $matchKey = $existing ? ($existing['key'] ?? 'unknown') : null;
314|
315|        if ($existing) {
316|            // Check for changes
317|            $changes = $this->detectChanges($existing['record'], $data);
318|
319|            if (! empty($changes)) {
320|                $this->importResults['changes'][] = [
321|                    'row' => $rowNumber,
322|                    'id' => $existing['record']->id,
323|                    'pc_name' => $existing['record']->pc_name,
324|                    'match_key' => $matchKey,
325|                    'changes' => $changes,
326|                ];
327|
328|                // Update the record
329|                if ($action === 'update' || $action === 'auto') {
330|                    $existing['record']->update($data);
331|                    $this->importResults['updated']++;
332|                }
333|            } else {
334|                $this->importResults['skipped']++;
335|            }
336|        } else {
337|            // Create new record
338|            if ($action === 'create' || $action === 'auto') {
339|                Hardware::create($data);
340|                $this->importResults['created']++;
341|            }
342|        }
343|    }
344|
345|    private function detectChanges(Hardware $existing, array $newData): array
346|    {
347|        $changes = [];
348|        $compareFields = [
349|            'n_code', 'type', 'os', 'ip_valid', 'ip_local', 'mac',
350|            'net_type', 'switch', 'port', 'shutdown', 'vlan',
351|            'motherboard', 'cpu', 'ram', 'hdd', 'comments', 'mark', 'clean_at',
352|        ];
353|
354|        foreach ($compareFields as $field) {
355|            $oldValue = $existing->$field;
356|            $newValue = $newData[$field] ?? null;
357|
358|            // Normalize for comparison
359|            $oldNormalized = $this->normalizeForComparison($oldValue);
360|            $newNormalized = $this->normalizeForComparison($newValue);
361|
362|            if ($oldNormalized !== $newNormalized) {
363|                $changes[$field] = [
364|                    'old' => $oldValue,
365|                    'new' => $newValue,
366|                ];
367|            }
368|        }
369|
370|        return $changes;
371|    }
372|
373|    private function normalizeForComparison($value): ?string
374|    {
375|        if ($value === null || $value === '' || $value === '\\\\\\\\\\\\\\\\N') {
376|            return '0'; // Treat null/empty as false for boolean comparison
377|        }
378|        if (is_bool($value)) {
379|            return $value ? '1' : '0';
380|        }
381|        // Handle boolean false/0 values that come from database
382|        if ($value === false || $value === 0 || $value === '0') {
383|            return '0';
384|        }
385|        if ($value === true || $value === 1 || $value === '1') {
386|            return '1';
387|        }
388|
389|        return trim((string) $value);
390|    }
391|
392|    private function parseBoolean($value): ?bool
393|    {
394|        if ($value === null || $value === '' || $value === '\\N') {
395|            return null;
396|        }
397|        $val = strtolower(trim((string) $value));
398|
399|        return in_array($val, ['1', 'true', 'yes', 'on', 'بله', 'تایید']);
400|    }
401|
402|    private function parseDate($value): ?string
403|    {
404|        if ($value === null || $value === '' || $value === '\\N') {
405|            return null;
406|        }
407|        $value = trim((string) $value);
408|        if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $value)) {
409|            return $value;
410|        }
411|
412|        return null;
413|    }
414|
415|    private function clean($value): ?string
416|    {
417|        if ($value === null || $value === '' || $value === '\\N' || trim((string) $value) === '') {
418|            return null;
419|        }
420|
421|        return trim((string) $value);
422|    }
423|
424|    public function rules(): array
425|    {
426|        return [
427|            'n_code' => 'required',
428|            'pc_name' => 'required|string|max:255',
429|            'type' => 'nullable|string|max:50',
430|            'os' => 'nullable|string|max:100',
431|            'ip_valid' => 'nullable|string|max:45',
432|            'ip_local' => 'nullable|string|max:45',
