13|/**
14| * @property int $id
15| * @property string $title
16| * @property Carbon|null $start_at
17| * @property Carbon|null $end_at
18| * @property bool $is_completed
19| * @property int $unit_id
20| * @property Carbon|null $created_at
21| * @property Carbon|null $updated_at
