3|namespace App\Services;
4|
5|use App\Models\Unit;
6|use App\Models\User;
7|use Illuminate\Support\Facades\Cache;
8|
9|class AccessService
10|{
11|    /**
12|     * واحدهای قابل دسترس کاربر (شامل خودش + تمام زیرمجموعه‌ها)
13|     *
14|     * @return array<int>
15|     */
16|    public function accessibleUnitIds(?User $user = null): array
17|    {
18|        $user ??= auth()->user();
19|
20|        if (! $user) {
21|            return [];
22|        }
23|
24|        $currentUnitId = session('current_unit_id');
25|
26|        if ($currentUnitId) {
27|            $baseUnitIds = [$currentUnitId];
28|        } else {
29|            $baseUnitIds = $user->units()->pluck('units.id')->toArray();
30|
31|            if (empty($baseUnitIds)) {
32|                $personUnitId = $user->person?->u_id;
33|                if ($personUnitId) {
34|                    $baseUnitIds = [$personUnitId];
35|                }
36|            }
37|        }
38|
39|        if (empty($baseUnitIds)) {
40|            return [];
41|        }
42|
43|        $sessionUnitId = session('current_unit_id', 'none');
44|        $cache = app(CacheInvalidationServiceInterface::class);
45|        $version = $cache->getVersion('unit_hierarchy');
46|        $sortedBase = $baseUnitIds;
47|        sort($sortedBase);
48|        $cacheKey = "accessible_units:v{$version}:{$user->id}:{$sessionUnitId}:".md5(json_encode($sortedBase));
49|
50|        return Cache::remember(
51|            $cacheKey,
52|            now()->addMinutes(30),
53|            fn () => Unit::descendantIds($baseUnitIds)->toArray()
54|        );
55|    }
56|
57|    /**
58|     * پاک کردن کش دسترسی کاربر (هنگام تغییر context یا تغییر واحدها)
59|     */
60|    public function clearCache(?User $user = null): void
61|    {
62|        $user ??= auth()->user();
63|
64|        if ($user) {
65|            // Bump the version counter so ANY versioned accessible_units key for this
66|            // hierarchy (including keys written under an older version) becomes
67|            // unreachable instead of surviving until TTL (fix for stale-cache bug).
68|            $cache = app(CacheInvalidationServiceInterface::class);
69|            $cache->increment('unit_hierarchy');
70|
71|            $currentUnitId = session('current_unit_id');
72|            $sessionUnitId = session('current_unit_id', 'none');
73|            $baseUnitIds = $currentUnitId
74|                ? [$currentUnitId]
75|                : $user->units()->pluck('units.id')->toArray();
76|
77|            // Forget the legacy unversioned key too.
78|            $cacheKey = "accessible_units:{$user->id}:{$sessionUnitId}:".md5(json_encode($baseUnitIds));
79|            Cache::forget($cacheKey);
80|        }
