{"content": "1|<?php
2|
3|namespace App\Services;
4|
5|use Carbon\Carbon;
6|use Illuminate\Database\Eloquent\Builder as EloquentBuilder;
7|use Illuminate\Database\Eloquent\Model;
8|use Illuminate\Database\Query\Builder as QueryBuilder;
9|use Illuminate\Support\Facades\DB;
10|
11|/**
12| * Daily counts over a date window, with the days that have no rows present as
13| * zero (issue #736).
14| *
15| * A `GROUP BY date(...)` aggregate only returns days that exist in the table, so
16| * a day with no tickets becomes a missing column — which reads as "no data"
17| * rather than "zero that day". Here the window is materialised with
18| * `generate_series` and left-joined against the aggregate, so the shape of the
19| * output depends only on the window, never on how the data happens to be
20| * distributed.
21| *
22| * Deliberately not read from `daily_reports`: that table is written by
23| * `reports:generate-daily` at 06:00, so it is always a day behind, and a failed
24| * schedule silently becomes a hole in the chart.
25| */
26|class DailySeries
27|{
28|    public const DEFAULT_DAYS = 30;
29|
30|    public const MAX_DAYS = 365;
31|
32|    public function __construct(
33|        private readonly int $days = self::DEFAULT_DAYS
34|    ) {}
35|
36|    /**
37|     * The last N days, ending today (inclusive). `days = 1` is today alone.
38|     */
39|    public static function lastDays(int $days): self
40|    {
41|        return new self($days);
42|    }
43|
44|    /**
45|     * An explicit inclusive range — for pages that already offer a
46|     * date-from/date-to picker and therefore have no single "last N days".
47|     */
48|    public static function between(Carbon $from, Carbon $to): self
49|    {
50|        $days = (int) $from->copy()->startOfDay()->diffInDays($to->copy()->startOfDay()) + 1;
51|
52|        return new self(max(1, $days));
53|    }
54|
55|    /**
56|     * Resolve a raw `?days=` value.
57|     *
58|     * A missing or non-numeric value falls back to the default rather than
59|     * erroring, so a sloppy `?days=abc` still renders a chart. Numeric values
60|     * outside 1..MAX are returned as-is and rejected by the validator, so the
61|     * client is told why instead of silently getting a different window.
62|     */
63|    public static function resolveDays(mixed $value): int
64|    {
65|        if ($value === null || $value === '' || ! is_numeric($value)) {
66|            return self::DEFAULT_DAYS;
67|        }
68|
69|        return (int) $value;
70|    }
71|
72|    /**
73|     * Counts per day over the window, ascending, one entry per day.
74|     *
75|     * `$query` is the caller's own already-filtered builder — unit scope, status
76|     * filter, whatever the page needs — so this fills gaps in an existing
77|     * aggregate instead of re-deriving its filters. A query that matches nothing
78|     * yields a full-length window of zeros, never a shorter one.
79|     *
80|     * Accepts either builder flavour; the helpers below narrow down what each
81|     * path needs, so neither case is handled twice.
82|     *
83|     * @param  EloquentBuilder<covariant Model>|QueryBuilder  $query
84|     * @return array<int, array{day: string, count: int}> Gregorian `Y-m-d` days.
85|     */
86|    public function counts(EloquentBuilder|QueryBuilder $query, string $dateColumn): array
87|    {
88|        [$from, $to] = $this->window();
89|
90|        $grammar = DB::connection()->getQueryGrammar();
91|        $wrappedDate = $grammar->wrap($this->qualifiedColumn($query, $dateColumn));
92|
93|        // The aggregate is a subquery built from the caller's builder, so all of
94|        // its filters and bindings are preserved. Identifiers are code
95|        // constants, never request input; the window is bound as two dates.
96|        $perDay = $this->toBaseQuery($query)
97|            ->selectRaw("date({$wrappedDate}) as day, COUNT(*) as count")
98|            ->groupByRaw("date({$wrappedDate})");
99|
100|        $rows = DB::select(
101|            'WITH days AS (
102|                SELECT generate_series(?::date, ?::date, interval \'1 day\')::date AS day
103|             )
104|             SELECT days.day::text AS day, COALESCE(per_day.count, 0) AS count
105|             FROM days
106|             LEFT JOIN ('.$perDay->toSql().') AS per_day ON per_day.day = days.day
107|             ORDER BY days.day',
108|            array_merge([$from, $to], $perDay->getBindings())
109|        );
110|
111|        return array_map(fn ($row) => [
112|            'day' => (string) $row->day,
113|            'count' => (int) $row->count,
114|        ], $rows);
115|    }
116|
117|    /**
118|     * The window as Gregorian `Y-m-d` bounds, oldest first.
119|     *
120|     * @return array{0: string, 1: string}
121|     */
122|    public function window(): array
123|    {
124|        $to = now()->startOfDay();
125|        $from = $to->copy()->subDays($this->days - 1);
126|
127|        return [$from->toDateString(), $to->toDateString()];
128|    }
129|
130|    /**
131|     * Table-qualify the date column when the builder knows its model, so a
132|     * joined aggregate cannot resolve the bare name to the wrong table.
133|     *
134|     * @param  EloquentBuilder<covariant Model>|QueryBuilder  $query
135|     */
136|    private function qualifiedColumn(EloquentBuilder|QueryBuilder $query, string $dateColumn): string
137|    {
138|        if (! $query instanceof EloquentBuilder) {
139|            return $dateColumn;
140|        }
141|
142|        return $query->getModel()->getTable().'.'.$dateColumn;
143|    }
144|
145|    /**
146|     * The underlying base builder — a clone, so adding the group-by never
147|     * mutates the caller's query.
148|     *
149|     * @param  EloquentBuilder<covariant Model>|QueryBuilder  $query
150|     */
151|    private function toBaseQuery(EloquentBuilder|QueryBuilder $query): QueryBuilder
152|    {
153|        return clone ($query instanceof EloquentBuilder ? $query->toBase() : $query);
154|    }
