13|use Illuminate\Support\Collection;
14|use Illuminate\Support\Facades\Cache;
15|use Illuminate\Support\Facades\DB;
16|
17|/**
18| * @property int $id
19| * @property int|null $region_id
20| * @property int|null $parent_id
21| * @property string $name
22| * @property int|null $unit_type_id
23| * @property float|null $lat
24| * @property float|null $lng
25| * @property string|null $description
26| * @property int|null $boundary_id
