28| * @property bool $can_receive_tickets
29| * @property Carbon|null $created_at
30| * @property Carbon|null $updated_at
31| * @property mixed $geom
32| * @property-read \Illuminate\Database\Eloquent\Collection<int, static> $children
33| * @property-read \Illuminate\Database\Eloquent\Collection<int, Person> $person
34| * @property-read UnitType|null $unitType
35| * @property-read Region|null $region
36| * @property-read static|null $parent
37| * @property-read Boundary|null $boundary
38| * @property-read \Illuminate\Database\Eloquent\Collection<int, Ticket> $tickets
39| * @property-read \Illuminate\Database\Eloquent\Collection<int, Todo> $todos
40| * @property-read \Illuminate\Database\Eloquent\Collection<int, User> $assignedUsers
41| * @property Collection<int, static> $childrenRecursive
42| *
43| * @method static Builder<static> where(string $column, mixed $value)
44| * @method static Builder<static> withinBounds(float $minLat, float $maxLat, float $minLng, float $maxLng)
45| * @method static Builder<static> nearby(float $lat, float $lng, float $radiusKm = 10)
46| * @method static Builder<static> containingPoint(float $lat, float $lng)
47| * @method static Builder<static> intersectsBoundary(string $wktPolygon)
48| * @method static Builder<static> subtree(int $unitId)
49| * @method static Builder<static> withPersonnelCount()
50| * @method static Builder<static> withinDistance(float $lat, float $lng, float $radiusMeters)
51| */
52|class Unit extends Model
53|{
54|    use HasFactory;
55|
56|    protected $fillable = [
57|        'name',
58|        'description',
59|        'region_id', // جایگزین province_id و county_id
60|        'parent_id',
61|        'unit_type_id',
62|        'boundary_id',
63|        'lat',
64|        'lng',
65|        'is_active',
66|        'can_receive_tickets',
67|    ];
68|
69|    protected $casts = [
70|        'can_receive_tickets' => 'boolean',
71|        'is_active' => 'boolean',
72|    ];
73|
74|    /**
75|     * Attributes that should be cast.
76|     * Using this instead of $attributes default since boolean cast
77|     * does not apply when the attribute isn't set by Eloquent.
78|     */
79|    protected $attributes = [
80|        'can_receive_tickets' => false,
81|    ];
82|
83|    public function person(): HasMany
84|    {
85|        return $this->hasMany(Person::class, 'u_id');
86|    }
87|
88|    public function unitType(): BelongsTo
89|    {
90|        return $this->belongsTo(UnitType::class);
91|    }
92|
93|    // رابطه با منطقه (استان یا شهرستان)
94|    public function region(): BelongsTo
95|    {
96|        return $this->belongsTo(Region::class);
97|    }
98|
99|    // رابطه برای ساختار سلسله‌مراتب: والد
100|    public function parent(): BelongsTo
101|    {
102|        return $this->belongsTo(Unit::class, 'parent_id');
103|    }
104|
105|    // رابطه برای ساختار سلسله‌مراتب: فرزندان
106|    public function children(): HasMany
107|    {
108|        return $this->hasMany(Unit::class, 'parent_id');
109|    }
110|
111|    public function boundary(): BelongsTo
112|    {
113|        return $this->belongsTo(Boundary::class, 'boundary_id');
114|    }
115|
116|    /**
117|     * Build full tree structure from a flat collection using a single CTE query.
118|     * Replaces the N+1 recursive eager loading pattern (childrenRecursive).
119|     *
120|     * @param  array<int>  $rootIds
121|     * @param  array<int>|null  $accessibleIds  If null, no scope filter applied
122|     * @return Collection<int, static>
123|     */
124|    public static function buildTree(array $rootIds, ?array $accessibleIds = null): Collection
125|    {
126|        if (empty($rootIds)) {
127|            return collect();
128|        }
129|
130|        // Single CTE: fetch all descendants of root units (inclusive)
131|        $allIds = self::descendantIds($rootIds)->all();
132|
133|        if (! empty($accessibleIds)) {
134|            $allIds = array_values(array_intersect($allIds, $accessibleIds));
135|        }
136|
137|        if (empty($allIds)) {
138|            return collect();
139|        }
140|
141|        // Single query: load all relevant units with their types
142|        $models = self::query()
143|            ->with('unitType')
144|            ->whereIn('units.id', $allIds)
145|            ->get();
146|
147|        /** @var array<int, static> $allUnits */
148|        $allUnits = [];
149|        /** @var array<int, list<static>> $childrenMap */
150|        $childrenMap = [];
151|        foreach ($models as $unit) {
152|            $allUnits[$unit->id] = $unit;
153|        }
154|
155|        // Build adjacency list
156|        foreach ($allUnits as $unit) {
157|            $parentId = $unit->parent_id;
158|            if ($parentId !== null && isset($allUnits[$parentId])) {
159|                $childrenMap[$parentId][] = $unit;
160|            }
161|        }
162|
163|        // Recursive closure to attach children
164|        $attachChildren = function (Unit $unit) use (&$attachChildren, $childrenMap): void {
165|            $unit->childrenRecursive = collect($childrenMap[$unit->id] ?? []);
166|            foreach ($unit->childrenRecursive as $child) {
167|                $attachChildren($child);
168|            }
169|        };
170|
171|        // Build root collection
172|        $roots = collect();
173|        foreach ($rootIds as $rootId) {
174|            if (isset($allUnits[$rootId])) {
175|                $roots[] = $allUnits[$rootId];
176|            }
177|        }
178|
179|        foreach ($roots as $root) {
180|            $attachChildren($root);
181|        }
182|
183|        return $roots;
184|    }
185|
186|    public function assignedUsers(): BelongsToMany
187|    {
188|        return $this->belongsToMany(User::class, 'user_units')
189|            ->withPivot('role', 'is_primary')
190|            ->withTimestamps();
191|    }
192|
193|    /**
194|     * Get ancestor (parent) IDs for a set of unit IDs — single JOIN query.
195|     *
196|     * @param  array<int>  $unitIds
197|     * @return Collection<int>
198|     */
199|    public static function ancestorIds(array $unitIds): Collection
200|    {
201|        $ids = array_values(array_filter($unitIds));
202|
203|        if (empty($ids)) {
204|            return collect();
205|        }
206|
207|        // Cache by sorted IDs to get consistent results regardless of input order
208|        $cache = app(CacheInvalidationServiceInterface::class);
209|        $version = $cache->getVersion('unit_hierarchy');
210|        $sorted = array_map('strval', $ids);
211|        sort($sorted, SORT_STRING);
212|        $cacheKey = 'unit_ancestors:v'.$version.':'.md5(implode(',', $sorted));
213|
214|        return Cache::remember(
215|            $cacheKey,
216|            now()->addMinutes(15), // Same TTL as descendantIds
217|            fn () => self::ancestorQuery($ids)
218|        );
219|    }
220|
221|    /**
222|     * Run the JOIN query for ancestor IDs.
223|     */
224|    protected static function ancestorQuery(array $ids): Collection
225|    {
226|        $placeholders = implode(',', array_fill(0, count($ids), '?'));
227|
228|        $results = DB::select("
229|            SELECT DISTINCT parent.id
230|            FROM units base
231|            INNER JOIN units parent ON parent.id = base.parent_id
232|            WHERE base.id IN ({$placeholders})
233|        ", $ids);
234|
235|        return collect($results)->pluck('id');
236|    }
237|
238|    /**
239|     * تمام id های زیرمجموعه (شامل خود واحدهای ورودی) با Recursive CTE
240|     *
241|     * @param  int|array<int>  $unitIds
242|     */
243|    public static function descendantIds(int|array $unitIds): Collection
244|    {
245|        $ids = is_array($unitIds) ? $unitIds : [$unitIds];
246|
247|        if (empty($ids)) {
248|            return collect();
249|        }
250|
251|        // Cache by sorted IDs to get consistent results regardless of input order
252|        $cache = app(CacheInvalidationServiceInterface::class);
253|        $version = $cache->getVersion('unit_hierarchy');
254|        $sorted = array_map('strval', $ids);
255|        sort($sorted, SORT_STRING);
256|        $cacheKey = 'unit_descendants:v'.$version.':'.md5(implode(',', $sorted));
257|
258|        return Cache::remember(
259|            $cacheKey,
260|            now()->addMinutes(15), // Shorter TTL to catch changes faster
261|            fn () => self::recursiveDescendantQuery($ids)
262|        );
263|    }
264|
265|    /**
266|     * Run the recursive CTE query for descendant IDs.
267|     *
268|     * UNION (not UNION ALL) is load-bearing: the set operator dedupes, so a
269|     * parent_id cycle terminates instead of recursing forever. UNION ALL on a
270|     * cyclic parent_id hangs the connection — parent_id is user-editable and
271|     * not constrained by the database, so the web form's type guard is not the
272|     * only possible writer.
273|     */
274|    protected static function recursiveDescendantQuery(array $ids): Collection
275|    {
276|        $placeholders = implode(',', array_fill(0, count($ids), '?'));
277|
278|        $results = DB::select("
279|            WITH RECURSIVE unit_tree AS (
280|                SELECT id FROM units WHERE id IN ({$placeholders})
281|                UNION
282|                SELECT u.id FROM units u
283|                INNER JOIN unit_tree ut ON u.parent_id = ut.id
284|                WHERE u.is_active = true
285|            )
286|            SELECT id FROM unit_tree
287|        ", $ids);
288|
289|        return collect($results)->pluck('id');
290|    }
291|
292|    /**
293|     * Scope for spatial queries: find units within a bounding box
294|     * Uses the composite lat/lng index for fast filtering
295|     */
296|    public function scopeWithinBounds($query, float $minLat, float $maxLat, float $minLng, float $maxLng)
297|    {
298|        return $query->whereBetween('lat', [$minLat, $maxLat])
299|            ->whereBetween('lng', [$minLng, $maxLng]);
300|    }
301|
302|    /**
303|     * Scope for spatial queries: find units within a radius of a point
304|     * Uses the composite lat/lng index for fast filtering
305|     */
306|    public function scopeNearby($query, float $lat, float $lng, float $radiusKm = 10)
307|    {
308|        // Approximate degrees per km (rough estimate for Iran region)
309|        $degPerKm = 0.009;
310|        $delta = $radiusKm * $degPerKm;
311|
312|        return $query->whereBetween('lat', [$lat - $delta, $lat + $delta])
313|            ->whereBetween('lng', [$lng - $delta, $lng + $delta]);
314|    }
315|
316|    /**
317|     * Scope for spatial queries: find units whose boundary contains a point
318|     * Uses the spatial index on boundaries.boundary
319|     * Optimized with EXISTS to better utilize spatial index
320|     */
321|    public function scopeContainingPoint($query, float $lat, float $lng)
322|    {
323|        // The unit↔boundary link is units.boundary_id (boundaries has no unit_id).
324|        return $query->whereHas('boundary', function ($q) use ($lat, $lng) {
325|            $q->whereRaw('ST_Contains(boundary, ST_GeomFromText(?, 4326))', ["POINT($lng $lat)"]);
326|        });
327|    }
328|
329|    /**
330|     * Scope for spatial queries: find units whose boundary intersects with a polygon
331|     * Uses the spatial index on boundaries.boundary
332|     */
333|    public function scopeIntersectsBoundary($query, string $wktPolygon)
334|    {
335|        return $query->whereHas('boundary', function ($q) use ($wktPolygon) {
336|            $q->whereRaw('ST_Intersects(boundary, ST_GeomFromText(?, 4326))', [$wktPolygon]);
337|        });
338|    }
339|
340|    /**
341|     * Scope: filter to only descendants of a given unit (inclusive) using the
342|     * existing descendantIds() CTE with caching.
343|     */
344|    public function scopeSubtree($query, int $unitId)
345|    {
346|        $descendantIds = self::descendantIds($unitId)->all();
347|
348|        return $query->whereIn('units.id', $descendantIds);
349|    }
350|
351|    /**
352|     * Scope: add withCount('person as personnel_count') in a chainable way.
353|     */
354|    public function scopeWithPersonnelCount($query)
355|    {
356|        return $query->withCount('person as personnel_count');
357|    }
358|
359|    /**
360|     * Scope for spatial queries: find units within a distance of a point (using ST_Distance_Sphere)
361|     * More accurate than bounding box but may be slower without proper spatial index
362|     */
363|    public function scopeWithinDistance($query, float $lat, float $lng, float $radiusMeters)
364|    {
365|        // PostGIS function name is ST_DistanceSphere (no underscore); the old
366|        // MySQL-style ST_Distance_Sphere does not exist on this stack.
367|        $pointWkt = "POINT($lng $lat)";
368|
369|        return $query->whereHas('boundary', function ($q) use ($pointWkt, $radiusMeters) {
370|            $q->whereRaw('ST_DistanceSphere(boundary, ST_GeomFromText(?, 4326)) <= ?', [$pointWkt, $radiusMeters]);
371|        });
372|    }
