2|
3|namespace App\Services;
4|
5|use App\Models\Unit;
6|use App\Traits\PersianNormalizer;
7|use Illuminate\Support\Collection;
8|
9|/**
10| * Tree queries for the unit hierarchy, consumed by the Livewire `unit.tree`
11| * component — its only real consumer today.
12| *
13| * Issue #704 (Plan 30). Every method takes the caller's accessible unit IDs as
14| * an argument rather than resolving them from the session: a future API caller
15| * gets its scope from `UnitScopedRequest`, not `auth()`, and passing them in
16| * keeps the service testable without a session.
17| *
18| * The `/api/hr/org-chart*` endpoints deliberately stay inline (comment in
19| * OrgChartController): they interleave person counts and Flutter-specific
20| * shaping into the tree walk, and HrApiTest gates their payload byte-identical.
21| * Converging them onto this service is a separate, test-gated change.
22| *
23| * Extract the logic here rather than copy-pasting it — a second feature that
24| * needs a unit tree (e.g. covered population per unit) plugs its own badge
25| * view into `unit.tree` and gets all of this for free.
26| *
27| * Query-shape note (PHPStan level 6, no larastan in this repo): every chain
28| * starts with `Unit::query()->with(...)`, where `query()` and `with()` are
29| * declared on `Eloquent\Builder`. An IN-filter goes inside a `where(Closure)`
30| * instead of a top-level `whereIn()`, because `whereIn` lives only on
31| * `Query\Builder` and resolves through `@mixin` — which types the rest of the
32| * chain as a query builder and makes `with()`/`get()` unreadable to PHPStan.
33| */
34|class UnitTreeService
35|{
36|    use PersianNormalizer;
37|
38|    /**
39|     * Shortest term (in CHARACTERS, not bytes) that triggers a search. The old
40|     * page gate was `strlen() > 2` — a byte count, so two Persian characters
41|     * (4 bytes) searched while one latin character did not. Two characters is
42|     * the closest deliberate equivalent; below it the result set is
43|     * effectively the whole scope, so the tree just resets its expansion.
44|     */
45|    private const MIN_SEARCH_LENGTH = 2;
46|
47|    /**
48|     * The roots of an access-scoped tree: accessible units whose parent is
49|     * either absent or OUTSIDE the scope.
50|     *
51|     * Scoping roots this way is what lets a user who can see a child unit but
52|     * not its parent still see that child — otherwise their tree renders empty
53|     * because the real top of the tree is hidden from them.
54|     *
55|     * @param  array<int>  $accessibleIds
56|     * @return Collection<int, Unit>
57|     */
58|    public function roots(array $accessibleIds): Collection
59|    {
60|        if ($accessibleIds === []) {
61|            return collect();
62|        }
63|
64|        return Unit::query()
65|            ->with(['unitType'])
66|            ->where(function ($query) use ($accessibleIds) {
67|                $query->whereIn('id', $accessibleIds);
68|            })
69|            ->where(function ($query) use ($accessibleIds) {
70|                $query->whereNull('parent_id')
71|                    ->orWhereNotIn('parent_id', $accessibleIds);
72|            })
73|            ->get();
74|    }
75|
76|    /**
77|     * Direct children of a unit, restricted to the scope.
78|     *
79|     * @param  array<int>  $accessibleIds
80|     * @return Collection<int, Unit>
81|     */
82|    public function childrenOf(int $unitId, array $accessibleIds): Collection
83|    {
84|        if ($accessibleIds === [] || ! in_array($unitId, $accessibleIds, true)) {
85|            return collect();
86|        }
87|
88|        return Unit::query()
89|            ->with(['unitType'])
90|            ->where('parent_id', $unitId)
91|            ->where(function ($query) use ($accessibleIds) {
92|                $query->whereIn('id', $accessibleIds);
93|            })
94|            ->get();
95|    }
96|
97|    /**
98|     * Children of SEVERAL parents in ONE query — the batch counterpart of
99|     * `childrenOf()`, so a tree level paints with a single round trip
100|     * instead of one query per node (issue #722: a 1→6→36 tree cost ~44
101|     * queries on initial paint when each node asked for its own children).
102|     *
103|     * Scope contract mirrors `childrenOf()`: the requested parents are
104|     * intersected with the scope FIRST, so an out-of-scope parent yields no
105|     * children — exactly as if `childrenOf()` had been called for it (a child
106|     * can never be in scope while its parent is not, but the method must stay
107|     * safe on its own). Empty inputs return an empty collection without
108|     * touching the database.
109|     *
110|     * Parents with no (in-scope) children get NO key in the result — callers
111|     * read with `->get($parentId, collect())`.
112|     *
113|     * @param  array<int>  $unitIds
114|     * @param  array<int>  $accessibleIds
115|     * @return Collection<int, Collection<int, Unit>> parent id => its children
116|     */
117|    public function childrenOfMany(array $unitIds, array $accessibleIds): Collection
118|    {
119|        $parentIds = array_values(array_intersect($unitIds, $accessibleIds));
120|
121|        if ($parentIds === []) {
122|            return collect();
123|        }
124|
125|        return Unit::query()
126|            ->with(['unitType'])
127|            ->where(function ($query) use ($parentIds, $accessibleIds) {
128|                $query->whereIn('parent_id', $parentIds)
129|                    ->whereIn('id', $accessibleIds);
130|            })
131|            ->get()
132|            ->groupBy('parent_id');
133|    }
134|
135|    /**
136|     * Whether a unit has at least one child the caller may see.
137|     *
138|     * Used by the tree's node template to decide whether to draw a toggle for
139|     * a unit whose children are not loaded yet. Existence only — the node
140|     * never needs the rows themselves, and this must not degrade into a
141|     * per-node full fetch on every render.
142|     *
143|     * @param  array<int>  $accessibleIds
144|     */
145|    public function hasChildren(int $unitId, array $accessibleIds): bool
146|    {
147|        if ($accessibleIds === [] || ! in_array($unitId, $accessibleIds, true)) {
148|            return false;
149|        }
150|
151|        return Unit::query()
152|            ->where(function ($query) use ($unitId, $accessibleIds) {
153|                $query->where('parent_id', $unitId)
154|                    ->whereIn('id', $accessibleIds);
155|            })
156|            ->exists();
157|    }
