159|    /**
160|     * Scope-restricted units whose name matches the term.
161|     *
162|     * Both sides of the comparison are folded: the term through
163|     * `foldedTerm()`, the column through `foldSeparatorsSql()`. Normalizing the
164|     * term alone is not enough — the stored text keeps its original code
165|     * points, so "حرفه‌ای" (with a ZWNJ) stays invisible to a search for
166|     * "حرفه ای" and "آموزش" to a search for "اموزش" (issue #705).
167|     *
168|     * @param  array<int>  $accessibleIds
169|     * @return Collection<int, Unit>
170|     */
171|    public function search(string $term, array $accessibleIds): Collection
172|    {
173|        $term = trim($term);
174|
175|        if (mb_strlen($term) < self::MIN_SEARCH_LENGTH || $accessibleIds === []) {
176|            return collect();
177|        }
178|
179|        $folded = self::foldedTerm($term);
180|
181|        return Unit::query()
182|            ->with(['unitType', 'parent'])
183|            ->where(function ($query) use ($accessibleIds, $folded) {
184|                $query->whereIn('id', $accessibleIds);
185|                $query->whereRaw(self::foldSeparatorsSql('name').' LIKE ?', ["%{$folded}%"]);
186|            })
187|            ->get();
188|    }
