190|    /**
191|     * The full ancestor chain of a unit, ordered root first, excluding the unit
192|     * itself. Stops at the scope boundary, so a chain never names a unit the
193|     * caller is not allowed to see.
194|     *
195|     * The walk keeps its own visited set: a `parent_id` cycle would otherwise
196|     * loop forever, and this runs per search match. Same guard the units
197|     * export's `buildHierarchy()` uses (issue #702). The chain is walked
198|     * through the `parent` relation rather than a per-hop `Unit::find()`,
199|     * matching how the original org chart walked it.
200|     *
201|     * @param  array<int>  $accessibleIds
202|     * @return Collection<int, Unit>
203|     */
204|    public function ancestorChain(Unit $unit, array $accessibleIds): Collection
205|    {
206|        $chain = collect();
207|        $visited = [(int) $unit->id => true];
208|        $current = $unit;
209|
210|        while ($current->parent_id) {
211|            $parentId = (int) $current->parent_id;
212|
213|            if (isset($visited[$parentId]) || ! in_array($parentId, $accessibleIds, true)) {
214|                break;
215|            }
216|
217|            $parent = $current->parent;
218|
219|            if (! $parent) {
220|                break;
221|            }
222|
223|            $chain->prepend($parent);
224|            $visited[$parentId] = true;
225|            $current = $parent;
226|        }
227|
228|        return $chain;
229|    }
