258|                'total' => $baseQuery->count(),
259|                'by_type' => (clone $baseQuery)->select('type', DB::raw('count(*) as count'))
260|                    ->groupBy('type')
261|                    ->pluck('count', 'type')
262|                    ->toArray(),
263|                'shutdown' => (clone $baseQuery)->where('shutdown', true)->count(),
264|            ];
265|        });
266|
