41|        RateLimiter::for('api-user', function ($request) {
42|            return Limit::perMinute(60)->by(
43|                $request->user()->id ?? $request->ip()
44|            );
45|        });
46|
47|        // Register anonymous help components with colon syntax for Blade
48|        Blade::component('components.help.button', 'help:button');
49|        Blade::component('components.help.modal', 'help:modal');
50|
