17|
18|    protected int $lastId = 0;
19|
20|    protected int $chunkSize = 500;
21|
22|    public function __construct(Builder $query)
23|    {
24|        $this->query = $query;
25|    }
26|
27|    /**
28|     * @return Collection<int, array>
29|     */
30|    public function collection(): Collection
31|    {
32|        // Return the raw models; Maatwebsite calls map() per row (WithMapping).
33|        return $this->query->with('user.person:id,n_code,f_name,l_name')
34|            ->latest('created_at')
35|            ->get();
36|    }
37|
38|    /**
39|     * Chunked export for large datasets — processes records in batches of $chunkSize
40|     * to avoid loading the entire result set into memory at once.
41|     */
42|    public function chunkCollection(): Collection
43|    {
44|        $chunk = $this->query
45|            ->with('user.person:id,n_code,f_name,l_name')
46|            ->where('id', '>', $this->lastId)
47|            ->orderBy('id')
48|            ->take($this->chunkSize)
49|            ->get();
50|
51|        if ($chunk->isNotEmpty()) {
52|            $this->lastId = $chunk->last()->id;
53|        }
54|
55|        return $chunk;
56|    }
