12|use Illuminate\Support\Str;
13|
14|class TicketController extends Controller
15|{
16|    public function index(UnitScopedRequest $request): AnonymousResourceCollection
17|    {
18|        $request->validate([
19|            'status' => 'sometimes|in:created,forwarded,accepted,completed,rejected',
20|            'priority' => 'sometimes|in:low,normal,urgent',
21|        ]);
22|
23|        $user = $request->user();
24|
25|        $query = Ticket::whereIn('unit_id', $request->accessibleIds())
26|            ->with(['unit:id,name', 'user:id,n_code', 'assignee:id,n_code']);
27|
28|        if ($request->filled('status')) {
29|            $query->where('status', $request->status);
30|        }
31|
32|        if ($request->filled('priority')) {
33|            $query->where('priority', $request->priority);
34|        }
35|
36|        if ($request->filled('assigned_to_me')) {
37|            $query->where('current_assignee_id', $user->id);
38|        }
39|
40|        $tickets = $query->latest()->paginate(20);
41|
42|        return TicketResource::collection($tickets);
43|    }
44|
45|    public function show(UnitScopedRequest $request, Ticket $ticket): JsonResponse
46|    {
47|        $result = $request->assertAccessibleUnit($ticket->unit_id);
48|        if ($result !== true) {
49|            return $result;
50|        }
51|
52|        return response()->json([
53|            'data' => new TicketResource($ticket->load([
54|                'unit:id,name',
55|                'user:id,n_code',
56|                'assignee:id,n_code',
57|                'activities' => fn ($q) => $q->latest()->with('user:id,n_code'),
58|                'attachments',
59|            ])),
60|        ]);
61|    }
62|
63|    public function store(UnitScopedRequest $request): JsonResponse
64|    {
65|        $validated = $request->validate([
66|            'subject' => 'required|string|max:255',
67|            'content' => 'required|string',
68|            'priority' => 'required|in:low,normal,urgent',
69|            'unit_id' => 'required|exists:units,id',
70|            'deadline' => 'nullable|date',
71|        ]);
72|
73|        $result = $request->assertAccessibleUnit($validated['unit_id']);
74|        if ($result !== true) {
75|            return $result;
76|        }
77|
78|        $ticket = Ticket::create([
79|            ...$validated,
80|            'ticket_code' => 'T-'.strtoupper(Str::random(8)),
81|            'user_id' => $request->user()->id,
82|            'status' => 'created',
83|        ]);
84|
85|        return response()->json([
86|            'success' => true,
87|            'data' => new TicketResource($ticket->load(['unit:id,name'])),
88|        ], 201);
89|    }
90|
91|    public function update(UnitScopedRequest $request, Ticket $ticket): JsonResponse
92|    {
93|        $result = $request->assertAccessibleUnit($ticket->unit_id);
94|        if ($result !== true) {
95|            return $result;
96|        }
97|
98|        $validated = $request->validate([
99|            'subject' => 'sometimes|required|string|max:255',
100|            'content' => 'sometimes|required|string',
101|            'priority' => 'sometimes|required|in:low,normal,urgent',
102|            'deadline' => 'nullable|date',
103|        ]);
104|
105|        $ticket->update($validated);
106|
107|        return response()->json([
108|            'success' => true,
109|            'data' => new TicketResource($ticket->fresh()->load(['unit:id,name'])),
110|        ]);
111|    }
112|
113|    public function destroy(UnitScopedRequest $request, Ticket $ticket): JsonResponse
114|    {
115|        $result = $request->assertAccessibleUnit($ticket->unit_id);
116|        if ($result !== true) {
117|            return $result;
118|        }
119|
120|        $ticket->delete();
121|
122|        return response()->json(['success' => true]);
123|    }
124|
125|    public function assign(UnitScopedRequest $request, Ticket $ticket): JsonResponse
126|    {
127|        $result = $request->assertAccessibleUnit($ticket->unit_id);
128|        if ($result !== true) {
129|            return $result;
130|        }
131|
132|        $validated = $request->validate([
133|            'assignee_id' => 'required|exists:users,id',
134|        ]);
135|
136|        $assignee = User::find($validated['assignee_id']);
137|
138|        // Issue #205: the assignee must belong to the ticket's organizational scope
139|        $assigneeUnitIds = $assignee->units()->pluck('units.id')->toArray();
140|        $assigneeUnitIds[] = $assignee->person?->u_id;
141|
142|        if (empty(array_intersect($assigneeUnitIds, $request->accessibleIds()))) {
143|            return response()->json(['message' => 'Assignee is not in an accessible unit.'], 403);
144|        }
145|
146|        $ticket->update([
147|            'current_assignee_id' => $validated['assignee_id'],
148|            'status' => 'forwarded',
149|        ]);
150|
151|        return response()->json([
152|            'success' => true,
153|            'data' => new TicketResource($ticket->fresh()->load(['unit:id,name', 'assignee:id,n_code'])),
154|        ]);
155|    }
156|
157|    public function accept(UnitScopedRequest $request, Ticket $ticket): JsonResponse
158|    {
159|        $result = $request->assertAccessibleUnit($ticket->unit_id);
160|        if ($result !== true) {
161|            return $result;
162|        }
163|
164|        // Issue #529: only the assigned user can accept the ticket
165|        if ($ticket->current_assignee_id !== $request->user()->id) {
166|            return response()->json(['message' => 'Only the assigned user can accept this ticket.'], 403);
167|        }
168|
169|        $ticket->update([
170|            'status' => 'accepted',
171|            'accepted_at' => now(),
172|        ]);
173|
174|        return response()->json([
175|            'success' => true,
176|            'data' => new TicketResource($ticket->fresh()->load(['unit:id,name', 'assignee:id,n_code'])),
177|        ]);
178|    }
179|
180|    public function complete(UnitScopedRequest $request, Ticket $ticket): JsonResponse
181|    {
