3|namespace App\Http\Controllers\Api;
4|
5|use App\Http\Controllers\Controller;
6|use App\Http\Requests\UnitScopedRequest;
7|use App\Jobs\SendNotificationJob;
8|use App\Models\Ticket;
9|use App\Models\TicketComment;
10|use App\Models\TicketCommentReaction;
11|use App\Models\User;
12|use Illuminate\Http\JsonResponse;
13|use Illuminate\Support\Facades\DB;
14|
15|class TicketCommentController extends Controller
16|{
17|    /**
18|     * List comments for a ticket.
19|     */
20|    public function index(UnitScopedRequest $request, Ticket $ticket): JsonResponse
21|    {
22|        $accessibleIds = $request->accessibleIds();
23|
24|        if (! in_array($ticket->unit_id, $accessibleIds)) {
25|            return response()->json(['message' => 'Ticket not accessible.'], 403);
26|        }
27|
28|        $threaded = $request->boolean('threaded');
29|        $perPage = min($request->integer('per_page', 20), 100);
30|
31|        $query = $ticket->comments()
32|            ->with(['user:id,n_code', 'reactions'])
33|            ->whereNull('parent_id')
34|            ->latest();
35|
36|        if ($threaded) {
37|            $comments = $query->with('children.user', 'children.reactions')
38|                ->paginate($perPage);
39|        } else {
40|            $comments = $query->paginate($perPage);
41|        }
42|
43|        return response()->json([
44|            'data' => $comments->items(),
45|            'meta' => [
46|                'current_page' => $comments->currentPage(),
47|                'last_page' => $comments->lastPage(),
48|                'per_page' => $comments->perPage(),
49|                'total' => $comments->total(),
50|            ],
51|        ]);
52|    }
53|
54|    /**
55|     * Create a new comment on a ticket.
56|     */
57|    public function store(UnitScopedRequest $request, Ticket $ticket): JsonResponse
58|    {
59|        $accessibleIds = $request->accessibleIds();
60|
61|        if (! in_array($ticket->unit_id, $accessibleIds)) {
62|            return response()->json(['message' => 'Ticket not accessible.'], 403);
63|        }
64|
65|        $validated = $request->validate([
66|            'body' => 'required|string|max:10000',
67|            'parent_id' => 'nullable|exists:ticket_comments,id',
68|        ]);
69|
70|        // If parent_id provided, verify it belongs to same ticket
71|        if ($validated['parent_id'] ?? null) {
72|            $parent = TicketComment::find($validated['parent_id']);
73|            if (! $parent || $parent->ticket_id !== $ticket->id) {
74|                return response()->json(['message' => 'Invalid parent comment.'], 422);
75|            }
76|            // Limit thread depth to 3
77|            $depth = $this->getThreadDepth($parent);
78|            if ($depth >= 3) {
79|                return response()->json(['message' => 'Maximum thread depth reached (3).'], 422);
80|            }
81|        }
82|
83|        // Process @mentions and markdown
84|        $bodyHtml = $this->processMarkdown($validated['body']);
85|        $mentions = $this->extractMentions($validated['body']);
86|
87|        $comment = TicketComment::create([
88|            'ticket_id' => $ticket->id,
89|            'user_id' => $request->user()->id,
90|            'parent_id' => $validated['parent_id'] ?? null,
91|            'body' => $validated['body'],
92|            'body_html' => $bodyHtml,
93|            'is_system' => false,
94|        ]);
95|
96|        // Notify mentioned users
97|        if (! empty($mentions)) {
98|            $this->notifyMentions($mentions, $comment, $request->user());
99|        }
100|
101|        // Notify parent comment author (if reply)
102|        if ($comment->parent_id) {
103|            $parentComment = TicketComment::find($comment->parent_id);
104|            if ($parentComment && $parentComment->user_id !== $request->user()->id) {
105|                $this->notifyReply($parentComment, $comment, $request->user());
106|            }
107|        }
108|
109|        return response()->json([
110|            'success' => true,
111|            'data' => $comment->load(['user:id,n_code', 'reactions']),
112|        ], 201);
113|    }
114|
115|    /**
116|     * Show a single comment.
117|     */
118|    public function show(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
119|    {
120|        $accessibleIds = $request->accessibleIds();
121|
122|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
123|            return response()->json(['message' => 'Comment not accessible.'], 403);
124|        }
125|
126|        return response()->json([
127|            'data' => $comment->load(['user:id,n_code', 'reactions', 'children.user:id,n_code']),
128|        ]);
129|    }
130|
131|    /**
132|     * Update a comment (author only, within 15 minutes).
133|     */
134|    public function update(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
135|    {
136|        $accessibleIds = $request->accessibleIds();
137|
138|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
139|            return response()->json(['message' => 'Comment not accessible.'], 403);
140|        }
141|
142|        if (! $comment->canBeEditedBy($request->user())) {
143|            return response()->json(['message' => 'Cannot edit this comment.'], 403);
144|        }
145|
146|        $validated = $request->validate([
147|            'body' => 'required|string|max:10000',
148|        ]);
149|
150|        $comment->update([
151|            'body' => $validated['body'],
152|            'body_html' => $this->processMarkdown($validated['body']),
153|        ]);
154|
155|        return response()->json([
156|            'success' => true,
157|            'data' => $comment->fresh()->load(['user:id,n_code', 'reactions']),
158|        ]);
159|    }
160|
161|    /**
162|     * Soft delete a comment (author or admin).
163|     */
164|    public function destroy(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
165|    {
166|        $accessibleIds = $request->accessibleIds();
167|
168|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
169|            return response()->json(['message' => 'Comment not accessible.'], 403);
170|        }
171|
172|        if (! $comment->canBeDeletedBy($request->user())) {
173|            return response()->json(['message' => 'Cannot delete this comment.'], 403);
174|        }
175|
176|        $comment->delete();
177|
178|        return response()->json(['success' => true]);
179|    }
180|
181|    /**
182|     * Add a reaction to a comment.
183|     */
184|    public function react(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
185|    {
186|        $accessibleIds = $request->accessibleIds();
187|
188|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
189|            return response()->json(['message' => 'Comment not accessible.'], 403);
190|        }
191|
192|        $validated = $request->validate([
193|            'reaction' => 'required|string|in:+1,-1,heart,tada,rocket,eyes',
194|        ]);
195|
196|        $reaction = TicketCommentReaction::firstOrCreate([
197|            'comment_id' => $comment->id,
198|            'user_id' => $request->user()->id,
199|            'reaction' => $validated['reaction'],
200|        ]);
201|
202|        // Notify comment author (batched - could be improved with a job)
203|        if ($comment->user_id !== $request->user()->id) {
204|            $this->notifyReaction($comment, $request->user(), $validated['reaction']);
205|        }
206|
207|        return response()->json([
208|            'success' => true,
209|            'data' => $reaction,
210|        ]);
211|    }
212|
213|    /**
214|     * Remove a reaction from a comment.
215|     */
216|    public function unreact(UnitScopedRequest $request, Ticket $ticket, TicketComment $comment): JsonResponse
217|    {
218|        $accessibleIds = $request->accessibleIds();
219|
220|        if (! in_array($ticket->unit_id, $accessibleIds) || $comment->ticket_id !== $ticket->id) {
221|            return response()->json(['message' => 'Comment not accessible.'], 403);
222|        }
223|
224|        $validated = $request->validate([
225|            'reaction' => 'required|string|in:+1,-1,heart,tada,rocket,eyes',
226|        ]);
227|
228|        TicketCommentReaction::where([
229|            'comment_id' => $comment->id,
230|            'user_id' => $request->user()->id,
231|            'reaction' => $validated['reaction'],
232|        ])->delete();
233|
234|        return response()->json(['success' => true]);
235|    }
